def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 100:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = op.count('C')
    op_d = n - op_c
    my_c = my.count('C')
    my_d = n - my_c

    last_me = my[-1]
    last_op = op[-1]

    remaining = 100 - n

    # Detect always-defect opponents
    if n >= 4 and op_d == n:
        return 'D'
    if n >= 8 and op_d >= n - 1:
        return 'D'

    # Detect always-cooperate opponents: exploit at the end
    if n >= 6 and op_c == n:
        if remaining <= 8:
            return 'D'
        return 'C'

    # Detect tit-for-tat-like: opponent tends to copy our previous action
    if n >= 6:
        mimic = 0
        for i in range(1, n):
            if op[i] == my[i - 1]:
                mimic += 1
        if mimic >= n - 2:
            if last_op == 'C':
                # If we played C, they played C: try one defect if enough rounds
                if remaining > 3:
                    return 'D'
                return 'C'
            else:
                return 'C'

    # Detect grim trigger: they defected after our first defection onward
    if n >= 5:
        first_def = -1
        for i in range(n):
            if my[i] == 'D':
                first_def = i
                break
        if first_def >= 0 and first_def < n - 1:
            after = op[first_def + 1:]
            if after and all(x == 'D' for x in after):
                return 'D'

    # Endgame exploitation based on opponent cooperation rate
    if remaining <= 1:
        if op_c * 2 > n:
            return 'D'
        if op_d * 2 > n:
            return 'D'
        return 'C'

    if remaining <= 3:
        if op_c * 3 > n * 2:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    if remaining <= 8:
        # Heavy cooperation from opponent -> exploit
        if op_c * 5 > n * 4:
            return 'D'
        # Defect streak -> keep defecting
        streak_d = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 'D':
                streak_d += 1
            else:
                break
        if streak_d >= 2:
            return 'D'
        return 'C'

    # Recent window analysis
    window = 10 if n >= 10 else n
    recent_op_c = 0
    for i in range(n - window, n):
        if op[i] == 'C':
            recent_op_c += 1
    recent_op_rate = recent_op_c / window if window > 0 else 0.5

    # Compute defection streaks
    streak_op_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            streak_op_d += 1
        else:
            break

    streak_op_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            streak_op_c += 1
        else:
            break

    # Highly cooperative opponent: cooperate but occasionally probe
    if recent_op_rate >= 0.8:
        if n >= 30 and n % 19 == 0 and remaining > 15:
            return 'D'
        return 'C'

    # Highly defective opponent: defect
    if recent_op_rate <= 0.25:
        return 'D'

    # Opponent just defected
    if last_op == 'D':
        if streak_op_d >= 3:
            # Long defection war: mostly defect, occasionally try C
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        if streak_op_d == 2:
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        # Single defection: retaliate but be willing to restore cooperation
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    # Opponent just cooperated
    # If we defected last round and they still cooperated, they are forgiving: continue cooperating
    if last_me == 'D' and last_op == 'C':
        return 'C'

    # If mutual cooperation has been strong, keep it up
    if n >= 2 and my[-1] == 'C' and op[-1] == 'C':
        # Rare probe with deterministic-ish condition
        if n > 25 and n % 23 == 0 and remaining > 12:
            return 'D'
        return 'C'

    return 'C'
